insert into public.recipes (slug, title, description, image_url, image_alt, prep_time, cook_time, rest_time, difficulty, cuisine, servings, rating, review_count, popularity, is_featured, is_vegetarian, is_vegan, is_gluten_free, is_dairy_free, calories, protein, carbohydrates, fat, nutrition_verified, notes, tags, created_at) values ('shakshuka-with-feta', 'Shakshuka with feta and herbs', 'Eggs gently poached in a smoky pepper and tomato sauce, finished with salty feta and a scatter of cilantro.', 'https://images.unsplash.com/photo-1590412200988-a436970781fa?auto=format&fit=crop&w=1200&q=80', 'A pan of shakshuka with eggs nestled in red tomato sauce and fresh herbs', 10, 25, 0, 'easy', 'Middle Eastern', 4, 4.8, 214, 94, true, true, false, true, false, 310, 17, 16, 20, false, 'The sauce can be made up to two days ahead. Reheat it until bubbling before adding the eggs.', array['one-pan', 'brunch', 'weekend']::text[], '2026-08-02T09:00:00Z');
insert into public.recipe_categories (recipe_id, category_id) select (select id from public.recipes where slug = 'shakshuka-with-feta'), id from public.categories where slug in ('breakfast', 'lunch');
