insert into public.recipe_steps (recipe_id, step_number, instruction) values
  ((select id from public.recipes where slug = 'shakshuka-with-feta'), 1, 'Warm the olive oil in a wide, deep frying pan over medium heat. Add the onion and pepper with a pinch of salt and cook for 8–10 minutes, stirring now and then, until soft and sweet.'),
  ((select id from public.recipes where slug = 'shakshuka-with-feta'), 2, 'Stir in the garlic, cumin, paprika and chilli flakes and cook for 1 minute, until fragrant.'),
  ((select id from public.recipes where slug = 'shakshuka-with-feta'), 3, 'Tip in the tomatoes, season well and simmer for 10 minutes, until the sauce has thickened enough to hold a hollow when you drag a spoon through it.'),
  ((select id from public.recipes where slug = 'shakshuka-with-feta'), 4, 'Make six small wells in the sauce and crack an egg into each. Cover the pan and cook over low heat for 5–7 minutes, until the whites are set but the yolks are still runny.'),
  ((select id from public.recipes where slug = 'shakshuka-with-feta'), 5, 'Scatter over the feta and cilantro, grind over some pepper and bring the pan straight to the table with toasted bread.');
insert into public.recipe_tips (recipe_id, position, tip) values
  ((select id from public.recipes where slug = 'shakshuka-with-feta'), 1, 'Crack each egg into a small cup first, then slide it into its well. You are far less likely to break a yolk.'),
  ((select id from public.recipes where slug = 'shakshuka-with-feta'), 2, 'Take the pan off the heat while the yolks still wobble. They keep cooking in the hot sauce.');
insert into public.recipe_substitutions (recipe_id, position, ingredient, substitute) values
  ((select id from public.recipes where slug = 'shakshuka-with-feta'), 1, 'feta', 'Crumbled goat''s cheese or a spoonful of thick yogurt'),
  ((select id from public.recipes where slug = 'shakshuka-with-feta'), 2, 'canned tomatoes', '1 kg very ripe fresh tomatoes, chopped, with 5 extra minutes of simmering');
insert into public.recipes (slug, title, description, image_url, image_alt, prep_time, cook_time, rest_time, difficulty, cuisine, servings, rating, review_count, popularity, is_featured, is_vegetarian, is_vegan, is_gluten_free, is_dairy_free, calories, protein, carbohydrates, fat, nutrition_verified, notes, tags, created_at) values ('buttermilk-pancakes', 'Fluffy buttermilk pancakes', 'Tall, tender pancakes with crisp edges. Buttermilk keeps them light and gives a gentle tang.', 'https://images.unsplash.com/photo-1567620905732-2d1ec7ab7445?auto=format&fit=crop&w=1200&q=80', 'A tall stack of golden pancakes topped with berries and syrup', 10, 20, 0, 'easy', 'American', 4, 4.7, 388, 91, false, true, false, false, false, 420, 12, 62, 13, false, null, array['weekend', 'kid-friendly', 'brunch']::text[], '2026-08-05T09:00:00Z');
insert into public.recipe_categories (recipe_id, category_id) select (select id from public.recipes where slug = 'buttermilk-pancakes'), id from public.categories where slug in ('breakfast');
insert into public.recipe_ingredients (recipe_id, ingredient_id, position, quantity, unit, note, is_optional) values
  ((select id from public.recipes where slug = 'buttermilk-pancakes'), 'flour', 1, 250, 'g', null, false),
  ((select id from public.recipes where slug = 'buttermilk-pancakes'), 'sugar', 2, 2, 'tbsp', null, false),
  ((select id from public.recipes where slug = 'buttermilk-pancakes'), 'baking-powder', 3, 2, 'tsp', null, false),
  ((select id from public.recipes where slug = 'buttermilk-pancakes'), 'baking-soda', 4, 0.5, 'tsp', null, false),
  ((select id from public.recipes where slug = 'buttermilk-pancakes'), 'salt', 5, 0.5, 'tsp', null, false),
  ((select id from public.recipes where slug = 'buttermilk-pancakes'), 'buttermilk', 6, 480, 'ml', null, false),
  ((select id from public.recipes where slug = 'buttermilk-pancakes'), 'eggs', 7, 2, null, null, false),
  ((select id from public.recipes where slug = 'buttermilk-pancakes'), 'butter', 8, 50, 'g', 'melted, plus extra for the pan', false),
  ((select id from public.recipes where slug = 'buttermilk-pancakes'), 'maple-syrup', 9, 4, 'tbsp', 'to serve', false),
  ((select id from public.recipes where slug = 'buttermilk-pancakes'), 'blueberries', 10, 150, 'g', 'to serve', true);
insert into public.recipe_steps (recipe_id, step_number, instruction) values
  ((select id from public.recipes where slug = 'buttermilk-pancakes'), 1, 'Whisk the flour, sugar, baking powder, baking soda and salt together in a large bowl.'),
  ((select id from public.recipes where slug = 'buttermilk-pancakes'), 2, 'In a jug, whisk the buttermilk and eggs, then whisk in the melted butter.'),
  ((select id from public.recipes where slug = 'buttermilk-pancakes'), 3, 'Pour the wet ingredients into the dry ones and fold with a spatula until just combined. A few lumps are fine. Rest the batter for 5 minutes.'),
  ((select id from public.recipes where slug = 'buttermilk-pancakes'), 4, 'Heat a non-stick pan over medium heat and brush with a little butter. Pour in about 60 ml of batter per pancake.'),
  ((select id from public.recipes where slug = 'buttermilk-pancakes'), 5, 'Cook for 2 minutes, until bubbles appear on the surface and the edges look set, then flip and cook for 1 minute more.'),
  ((select id from public.recipes where slug = 'buttermilk-pancakes'), 6, 'Keep warm in a low oven while you cook the rest. Serve stacked, with maple syrup and blueberries.');
insert into public.recipe_tips (recipe_id, position, tip) values
  ((select id from public.recipes where slug = 'buttermilk-pancakes'), 1, 'Over-mixing develops gluten and makes tough pancakes. Stop as soon as no dry flour is visible.'),
  ((select id from public.recipes where slug = 'buttermilk-pancakes'), 2, 'Your first pancake tells you if the pan is too hot. Adjust the heat before cooking the rest.');
