  ((select id from public.recipes where slug = 'avocado-toast-jammy-eggs'), 1, 'Bring a small pan of water to a rolling boil. Lower in the eggs and cook for exactly 6½ minutes.'),
  ((select id from public.recipes where slug = 'avocado-toast-jammy-eggs'), 2, 'Move the eggs to a bowl of cold water for 2 minutes, then peel carefully.'),
