insert into public.recipe_steps (recipe_id, step_number, instruction) values
  ((select id from public.recipes where slug = 'strawberry-chia-pudding'), 1, 'Whisk the almond milk, chia seeds, maple syrup and vanilla in a bowl. Leave for 10 minutes, then whisk again to break up any clumps.'),
  ((select id from public.recipes where slug = 'strawberry-chia-pudding'), 2, 'Cover and refrigerate for at least 4 hours, or overnight, until thick and spoonable.'),
  ((select id from public.recipes where slug = 'strawberry-chia-pudding'), 3, 'Roughly crush half the strawberries with a fork and the lime juice. Slice the rest.'),
  ((select id from public.recipes where slug = 'strawberry-chia-pudding'), 4, 'Layer the pudding and crushed strawberries in glasses and top with the sliced berries.');
insert into public.recipe_tips (recipe_id, position, tip) values
  ((select id from public.recipes where slug = 'strawberry-chia-pudding'), 1, 'The second whisk after 10 minutes is what stops the seeds settling into a solid layer.');
