insert into public.recipe_steps (recipe_id, step_number, instruction) values
  ((select id from public.recipes where slug = 'brioche-french-toast'), 1, 'Whisk the eggs, milk, sugar, cinnamon and vanilla in a shallow dish.'),
  ((select id from public.recipes where slug = 'brioche-french-toast'), 2, 'Lay the brioche in the custard for about 20 seconds per side, so it soaks through without falling apart.'),
  ((select id from public.recipes where slug = 'brioche-french-toast'), 3, 'Melt half the butter in a large frying pan over medium-low heat. Fry two slices for 2–3 minutes per side, until deep golden.'),
  ((select id from public.recipes where slug = 'brioche-french-toast'), 4, 'Repeat with the remaining butter and brioche.'),
  ((select id from public.recipes where slug = 'brioche-french-toast'), 5, 'Warm the blueberries in the pan with a splash of the maple syrup for 1 minute. Spoon over the toast and finish with the rest of the syrup and a dusting of sugar.');
