insert into public.recipe_steps (recipe_id, step_number, instruction) values
  ((select id from public.recipes where slug = 'blueberry-muffins'), 1, 'Heat the oven to 220°C (200°C fan) and line a 12-hole muffin tin with paper cases.'),
  ((select id from public.recipes where slug = 'blueberry-muffins'), 2, 'Whisk the flour, sugar, baking powder, salt and lemon zest in a large bowl.'),
  ((select id from public.recipes where slug = 'blueberry-muffins'), 3, 'In a jug, whisk the eggs, milk, oil and vanilla. Pour into the dry ingredients and fold until barely combined.'),
  ((select id from public.recipes where slug = 'blueberry-muffins'), 4, 'Fold in the blueberries, then divide the batter between the cases. They will be very full.'),
  ((select id from public.recipes where slug = 'blueberry-muffins'), 5, 'Bake for 5 minutes, then reduce the oven to 180°C (160°C fan) and bake for 15–17 minutes more, until a skewer comes out clean.'),
  ((select id from public.recipes where slug = 'blueberry-muffins'), 6, 'Cool in the tin for 5 minutes, then move to a wire rack.');
insert into public.recipe_tips (recipe_id, position, tip) values
  ((select id from public.recipes where slug = 'blueberry-muffins'), 1, 'The blast of high heat at the start is what gives the muffins tall, domed tops.'),
  ((select id from public.recipes where slug = 'blueberry-muffins'), 2, 'Toss frozen blueberries in a spoonful of flour so they don''t sink or bleed into the batter.');
insert into public.recipe_substitutions (recipe_id, position, ingredient, substitute) values
  ((select id from public.recipes where slug = 'blueberry-muffins'), 1, 'blueberries', 'Raspberries or chopped strawberries');
