insert into public.recipe_steps (recipe_id, step_number, instruction) values
  ((select id from public.recipes where slug = 'margherita-pizza'), 1, 'Mix the flour, yeast and salt in a large bowl. Add the water and olive oil and bring together into a shaggy dough.'),
  ((select id from public.recipes where slug = 'margherita-pizza'), 2, 'Knead on a lightly floured surface for 8–10 minutes, until smooth and springy. Return to the bowl, cover and leave somewhere warm for 1½–2 hours, until doubled.'),
  ((select id from public.recipes where slug = 'margherita-pizza'), 3, 'Put a heavy baking tray or pizza stone on the top shelf and heat the oven as high as it goes (at least 250°C) for 30 minutes.'),
  ((select id from public.recipes where slug = 'margherita-pizza'), 4, 'Season the passata with a pinch of salt. Divide the dough into two and stretch each piece into a 30 cm round on a floured sheet of baking paper.'),
  ((select id from public.recipes where slug = 'margherita-pizza'), 5, 'Spread each base thinly with passata and scatter with mozzarella. Slide the paper onto the hot tray and bake for 8–10 minutes, until the crust is blistered and the cheese bubbling.'),
  ((select id from public.recipes where slug = 'margherita-pizza'), 6, 'Finish with basil, a drizzle of olive oil and parmesan, if using. Slice and eat straight away.');
insert into public.recipe_tips (recipe_id, position, tip) values
  ((select id from public.recipes where slug = 'margherita-pizza'), 1, 'Press the dough out with your fingertips rather than a rolling pin to keep the air in the rim.'),
  ((select id from public.recipes where slug = 'margherita-pizza'), 2, 'Squeeze excess water from the mozzarella so the centre doesn''t go soggy.');
insert into public.recipe_substitutions (recipe_id, position, ingredient, substitute) values
  ((select id from public.recipes where slug = 'margherita-pizza'), 1, 'strong bread flour', 'Italian ''00'' flour'),
  ((select id from public.recipes where slug = 'margherita-pizza'), 2, 'fresh mozzarella', 'Low-moisture mozzarella, grated');
