  ((select id from public.recipes where slug = 'mushroom-risotto'), 'black-pepper', 13, null, null, 'to taste', false);
insert into public.recipe_steps (recipe_id, step_number, instruction) values
  ((select id from public.recipes where slug = 'mushroom-risotto'), 1, 'Heat the olive oil in a wide pan over high heat. Fry the mushrooms in two batches without stirring too often, until well browned. Season and set aside.'),
  ((select id from public.recipes where slug = 'mushroom-risotto'), 2, 'Lower the heat, add half the butter and cook the shallot, garlic and thyme for 4–5 minutes, until soft.'),
  ((select id from public.recipes where slug = 'mushroom-risotto'), 3, 'Add the rice and stir for 2 minutes, until the edges of the grains turn translucent. Pour in the wine and let it bubble away.'),
  ((select id from public.recipes where slug = 'mushroom-risotto'), 4, 'Add the hot stock a ladle at a time, stirring often and waiting until each addition is almost absorbed before adding the next. This takes 18–20 minutes.'),
  ((select id from public.recipes where slug = 'mushroom-risotto'), 5, 'When the rice is tender with a slight bite, stir in most of the mushrooms, the parmesan and the remaining butter. Cover and rest for 2 minutes.'),
  ((select id from public.recipes where slug = 'mushroom-risotto'), 6, 'The risotto should flow gently when spooned onto a plate. Loosen with a splash of stock if needed, then top with the remaining mushrooms and parsley.');
insert into public.recipe_tips (recipe_id, position, tip) values
  ((select id from public.recipes where slug = 'mushroom-risotto'), 1, 'Crowding the pan makes mushrooms steam instead of brown. Cook them in batches.');
insert into public.recipe_substitutions (recipe_id, position, ingredient, substitute) values
  ((select id from public.recipes where slug = 'mushroom-risotto'), 1, 'white wine', 'An extra ladle of stock with 1 tsp white wine vinegar');
insert into public.recipes (slug, title, description, image_url, image_alt, prep_time, cook_time, rest_time, difficulty, cuisine, servings, rating, review_count, popularity, is_featured, is_vegetarian, is_vegan, is_gluten_free, is_dairy_free, calories, protein, carbohydrates, fat, nutrition_verified, notes, tags, created_at) values ('lemon-herb-roast-chicken', 'Lemon and herb roast chicken', 'A golden, juicy whole chicken roasted over potatoes that soak up every drop of lemony, garlicky juice.', 'https://images.unsplash.com/photo-1598103442097-8b74394b95c6?auto=format&fit=crop&w=1200&q=80', 'A whole roast chicken with crisp golden skin in a cast-iron pan', 15, 80, 15, 'medium', 'French', 4, 4.8, 276, 88, true, false, false, true, true, 640, 48, 38, 32, false, null, array['sunday-lunch', 'one-pan']::text[], '2026-08-27T09:00:00Z');
