insert into public.recipe_ingredients (recipe_id, ingredient_id, position, quantity, unit, note, is_optional) values
  ((select id from public.recipes where slug = 'lemon-herb-roast-chicken'), 'whole-chicken', 1, 1, null, 'about 1.6 kg', false),
  ((select id from public.recipes where slug = 'lemon-herb-roast-chicken'), 'lemon', 2, 1, null, null, false),
