insert into public.recipe_steps (recipe_id, step_number, instruction) values
  ((select id from public.recipes where slug = 'lemon-herb-roast-chicken'), 1, 'Take the chicken out of the fridge 30 minutes before cooking. Heat the oven to 220°C (200°C fan).'),
  ((select id from public.recipes where slug = 'lemon-herb-roast-chicken'), 2, 'Toss the potatoes and onions in a roasting tin with 2 tbsp olive oil, salt and pepper.'),
  ((select id from public.recipes where slug = 'lemon-herb-roast-chicken'), 3, 'Halve the lemon and put it inside the chicken with half the herbs and four garlic cloves. Rub the skin with the remaining oil and season generously.'),
  ((select id from public.recipes where slug = 'lemon-herb-roast-chicken'), 4, 'Sit the chicken on the potatoes, scatter around the remaining garlic and herbs, and roast for 20 minutes.'),
  ((select id from public.recipes where slug = 'lemon-herb-roast-chicken'), 5, 'Reduce the oven to 190°C (170°C fan) and roast for a further 55–60 minutes, until the juices run clear when the thickest part of the thigh is pierced (75°C on a thermometer).'),
  ((select id from public.recipes where slug = 'lemon-herb-roast-chicken'), 6, 'Rest the chicken for 15 minutes before carving. Toss the potatoes in the pan juices and return them to the oven while it rests.');
insert into public.recipe_tips (recipe_id, position, tip) values
  ((select id from public.recipes where slug = 'lemon-herb-roast-chicken'), 1, 'Patting the skin completely dry, or leaving the chicken uncovered in the fridge overnight, gives the crispest skin.'),
  ((select id from public.recipes where slug = 'lemon-herb-roast-chicken'), 2, 'Squeeze the soft roasted garlic out of its skins and stir it through the juices.');
insert into public.recipe_substitutions (recipe_id, position, ingredient, substitute) values
  ((select id from public.recipes where slug = 'lemon-herb-roast-chicken'), 1, 'whole chicken', '1.2 kg bone-in chicken thighs, roasted for 40–45 minutes');
