insert into public.recipes (slug, title, description, image_url, image_alt, prep_time, cook_time, rest_time, difficulty, cuisine, servings, rating, review_count, popularity, is_featured, is_vegetarian, is_vegan, is_gluten_free, is_dairy_free, calories, protein, carbohydrates, fat, nutrition_verified, notes, tags, created_at) values ('shoyu-ramen-with-prawns', 'Shoyu ramen with prawns', 'A clear, soy-seasoned broth with sweet prawns, springy noodles, greens and marinated soft-boiled eggs.', 'https://images.unsplash.com/photo-1569718212165-3a8278d5f624?auto=format&fit=crop&w=1200&q=80', 'A bowl of ramen with prawns, halved soft-boiled eggs, greens and chopsticks', 25, 50, 0, 'advanced', 'Japanese', 4, 4.8, 231, 89, true, false, false, false, true, 540, 34, 66, 14, false, 'The broth and eggs both improve if made a day ahead. Keep the eggs in their marinade for up to 2 days.', array['project', 'comfort', 'weekend']::text[], '2026-09-08T09:00:00Z');
insert into public.recipe_categories (recipe_id, category_id) select (select id from public.recipes where slug = 'shoyu-ramen-with-prawns'), id from public.categories where slug in ('dinner');
