insert into public.recipe_steps (recipe_id, step_number, instruction) values
  ((select id from public.recipes where slug = 'shoyu-ramen-with-prawns'), 1, 'Put the stock, ginger, garlic, spring onion whites and dried shiitake in a large pan. Bring to a bare simmer and cook gently for 40 minutes to infuse.'),
  ((select id from public.recipes where slug = 'shoyu-ramen-with-prawns'), 2, 'Meanwhile, boil the eggs for 6½ minutes, cool in iced water and peel. Mix 3 tbsp of the soy sauce with the mirin and 3 tbsp water and marinate the eggs in it for at least 30 minutes.'),
  ((select id from public.recipes where slug = 'shoyu-ramen-with-prawns'), 3, 'Strain the broth and return it to the pan. Season with the remaining soy sauce, tasting as you go, and keep at a gentle simmer.'),
  ((select id from public.recipes where slug = 'shoyu-ramen-with-prawns'), 4, 'Add the prawns to the broth and poach for 2–3 minutes, until pink and just firm. Lift them out with a slotted spoon.'),
  ((select id from public.recipes where slug = 'shoyu-ramen-with-prawns'), 5, 'Cook the noodles according to the packet, adding the spinach for the final 30 seconds, then drain well.'),
  ((select id from public.recipes where slug = 'shoyu-ramen-with-prawns'), 6, 'Divide the noodles and spinach between warm bowls, ladle over the hot broth and drizzle with sesame oil. Top with the prawns, halved eggs, sliced spring onion greens and sesame seeds.');
insert into public.recipe_tips (recipe_id, position, tip) values
  ((select id from public.recipes where slug = 'shoyu-ramen-with-prawns'), 1, 'Never let the broth boil hard. A gentle simmer keeps it clear.'),
  ((select id from public.recipes where slug = 'shoyu-ramen-with-prawns'), 2, 'Overcooked prawns turn rubbery. Pull them out as soon as they curl into a loose C.');
insert into public.recipe_substitutions (recipe_id, position, ingredient, substitute) values
  ((select id from public.recipes where slug = 'shoyu-ramen-with-prawns'), 1, 'prawns', 'Sliced poached chicken thigh or pan-fried tofu'),
  ((select id from public.recipes where slug = 'shoyu-ramen-with-prawns'), 2, 'fresh ramen noodles', 'Dried ramen or rice noodles (for gluten-free, with tamari)');
