insert into public.recipe_steps (recipe_id, step_number, instruction) values
  ((select id from public.recipes where slug = 'chipotle-chicken-tacos'), 1, 'Mix the chipotle, juice of 1 lime, garlic, cumin, olive oil and a good pinch of salt. Toss the chicken in it and leave for 10 minutes.'),
  ((select id from public.recipes where slug = 'chipotle-chicken-tacos'), 2, 'Put the red onion in a bowl with the juice of half a lime and a pinch of salt. Scrunch together and set aside to pickle.'),
  ((select id from public.recipes where slug = 'chipotle-chicken-tacos'), 3, 'Heat a griddle or heavy frying pan over high heat. Cook the chicken for 5–6 minutes per side, until charred and cooked through. Rest for 5 minutes, then slice.'),
