insert into public.recipe_steps (recipe_id, step_number, instruction) values
  ((select id from public.recipes where slug = 'thai-red-curry'), 1, 'Heat the oil in a wok or deep pan over medium heat. Fry the curry paste for 1–2 minutes, until it smells fragrant.'),
  ((select id from public.recipes where slug = 'thai-red-curry'), 2, 'Add a few spoonfuls of the thick cream from the top of the coconut milk and fry until the oil starts to separate.'),
  ((select id from public.recipes where slug = 'thai-red-curry'), 3, 'Add the chicken and stir to coat, then pour in the rest of the coconut milk with 100 ml water. Simmer for 10 minutes.'),
  ((select id from public.recipes where slug = 'thai-red-curry'), 4, 'Add the pepper and green beans and cook for 4–5 minutes, until just tender.'),
  ((select id from public.recipes where slug = 'thai-red-curry'), 5, 'Season with the fish sauce, sugar and a squeeze of lime. Stir through the basil and serve with rice.');
insert into public.recipe_tips (recipe_id, position, tip) values
  ((select id from public.recipes where slug = 'thai-red-curry'), 1, 'Curry pastes vary a lot in heat. Start with 2 tbsp and add more to taste.');
insert into public.recipe_substitutions (recipe_id, position, ingredient, substitute) values
  ((select id from public.recipes where slug = 'thai-red-curry'), 1, 'chicken', 'Prawns (add them with the vegetables) or tofu'),
  ((select id from public.recipes where slug = 'thai-red-curry'), 2, 'fish sauce', 'Soy sauce, for a fish-free curry (check your curry paste too)');
