insert into public.recipe_steps (recipe_id, step_number, instruction) values
  ((select id from public.recipes where slug = 'vegetable-fried-rice'), 1, 'Break up the cold rice with your fingers so there are no clumps.'),
  ((select id from public.recipes where slug = 'vegetable-fried-rice'), 2, 'Heat a wok over high heat until smoking. Add half the oil and the eggs, if using, scramble briefly and tip onto a plate.'),
  ((select id from public.recipes where slug = 'vegetable-fried-rice'), 3, 'Add the remaining oil with the garlic, ginger and carrot and stir-fry for 2 minutes.'),
  ((select id from public.recipes where slug = 'vegetable-fried-rice'), 4, 'Add the rice and peas and stir-fry for 4–5 minutes, pressing the rice against the hot wok so it toasts.'),
  ((select id from public.recipes where slug = 'vegetable-fried-rice'), 5, 'Add the soy sauce, sesame oil, spring onions and egg, toss everything together and serve.');
insert into public.recipe_tips (recipe_id, position, tip) values
  ((select id from public.recipes where slug = 'vegetable-fried-rice'), 1, 'Freshly cooked rice turns mushy. Use cold rice, or spread fresh rice on a tray and chill it for an hour.');
