insert into public.recipe_steps (recipe_id, step_number, instruction) values
  ((select id from public.recipes where slug = 'smash-burgers'), 1, 'Mix the mayonnaise, ketchup and mustard with a splash of pickle juice to make the sauce.'),
  ((select id from public.recipes where slug = 'smash-burgers'), 2, 'Divide the beef into 8 loose balls. Do not season yet.'),
  ((select id from public.recipes where slug = 'smash-burgers'), 3, 'Toast the cut sides of the buns in a large dry cast-iron pan, then set aside. Turn the heat to high and add the oil.'),
  ((select id from public.recipes where slug = 'smash-burgers'), 4, 'Put two balls in the pan and press down hard with a sturdy spatula until about 1 cm thick. Season with salt and pepper and cook for 2 minutes without moving.'),
  ((select id from public.recipes where slug = 'smash-burgers'), 5, 'Scrape under the crust and flip. Add a slice of cheese to one patty and stack the other on top. Cook for 1 minute more. Repeat with the rest.'),
  ((select id from public.recipes where slug = 'smash-burgers'), 6, 'Spread the buns with sauce and build the burgers with lettuce, onion, pickles and the stacked patties.');
insert into public.recipe_tips (recipe_id, position, tip) values
  ((select id from public.recipes where slug = 'smash-burgers'), 1, 'Press within the first 30 seconds, while the meat is still cold. Pressing later squeezes out the juices.');
