insert into public.recipe_steps (recipe_id, step_number, instruction) values
  ((select id from public.recipes where slug = 'greek-salad'), 1, 'Put the tomatoes, cucumber, onion and pepper in a wide shallow bowl. Season with salt and leave for 5 minutes so the tomatoes release some juice.'),
  ((select id from public.recipes where slug = 'greek-salad'), 2, 'Drizzle with the vinegar and most of the olive oil and toss gently.'),
