insert into public.recipe_steps (recipe_id, step_number, instruction) values
  ((select id from public.recipes where slug = 'classic-tiramisu'), 1, 'Whisk the egg yolks and sugar for 3–4 minutes, until pale and thick. Beat in the mascarpone until smooth.'),
  ((select id from public.recipes where slug = 'classic-tiramisu'), 2, 'In a clean bowl, whisk the egg whites to stiff peaks, then fold them into the mascarpone mixture in three additions.'),
  ((select id from public.recipes where slug = 'classic-tiramisu'), 3, 'Mix the coffee with the Marsala, if using, in a shallow dish.'),
  ((select id from public.recipes where slug = 'classic-tiramisu'), 4, 'Dip half the ladyfingers briefly in the coffee, one at a time, and lay them in a 20 × 30 cm dish. Spread over half the cream.'),
  ((select id from public.recipes where slug = 'classic-tiramisu'), 5, 'Repeat with the remaining ladyfingers and cream. Cover and chill for at least 6 hours, or overnight.'),
  ((select id from public.recipes where slug = 'classic-tiramisu'), 6, 'Dust generously with cocoa just before serving.');
insert into public.recipe_tips (recipe_id, position, tip) values
  ((select id from public.recipes where slug = 'classic-tiramisu'), 1, 'A one-second dip per side is enough. Soggy ladyfingers make a watery tiramisu.');
insert into public.recipe_substitutions (recipe_id, position, ingredient, substitute) values
  ((select id from public.recipes where slug = 'classic-tiramisu'), 1, 'Marsala', 'Dark rum, brandy, or leave it out entirely');
