insert into public.recipe_steps (recipe_id, step_number, instruction) values
  ((select id from public.recipes where slug = 'banana-bread'), 1, 'Heat the oven to 175°C (155°C fan). Grease and line a 900 g loaf tin.'),
  ((select id from public.recipes where slug = 'banana-bread'), 2, 'Mix the mashed banana, melted butter and brown sugar in a large bowl, then beat in the eggs and vanilla.'),
  ((select id from public.recipes where slug = 'banana-bread'), 3, 'Add the flour, baking soda, cinnamon and salt and fold until just combined. Fold in the walnuts, if using.'),
  ((select id from public.recipes where slug = 'banana-bread'), 4, 'Scrape into the tin and bake for 55–65 minutes, until a skewer comes out clean. Cover loosely with foil if it browns too quickly.'),
  ((select id from public.recipes where slug = 'banana-bread'), 5, 'Cool in the tin for 10 minutes, then turn out onto a rack.');
