insert into public.recipe_ingredients (recipe_id, ingredient_id, position, quantity, unit, note, is_optional) values
  ((select id from public.recipes where slug = 'no-knead-country-loaf'), 'bread-flour', 1, 500, 'g', 'plus extra for dusting', false),
  ((select id from public.recipes where slug = 'no-knead-country-loaf'), 'yeast', 2, 0.5, 'tsp', null, false),
  ((select id from public.recipes where slug = 'no-knead-country-loaf'), 'salt', 3, 10, 'g', null, false),
  ((select id from public.recipes where slug = 'no-knead-country-loaf'), 'water', 4, 400, 'ml', 'cool', false);
insert into public.recipe_steps (recipe_id, step_number, instruction) values
  ((select id from public.recipes where slug = 'no-knead-country-loaf'), 1, 'Stir the flour, yeast, salt and water together in a large bowl until no dry flour remains. Cover and leave at room temperature for 12–18 hours, until bubbly and more than doubled.'),
  ((select id from public.recipes where slug = 'no-knead-country-loaf'), 2, 'Turn the dough onto a well-floured surface and fold it over itself a few times to form a rough ball.'),
  ((select id from public.recipes where slug = 'no-knead-country-loaf'), 3, 'Place seam-side down on a floured sheet of baking paper, cover and leave for 1–2 hours, until puffy.'),
  ((select id from public.recipes where slug = 'no-knead-country-loaf'), 4, 'Meanwhile, put a lidded cast-iron pot in the oven and heat to 240°C (220°C fan) for 30 minutes.'),
  ((select id from public.recipes where slug = 'no-knead-country-loaf'), 5, 'Lift the dough on its paper into the hot pot. Cover and bake for 30 minutes, then uncover and bake for 15 minutes more, until deep brown.'),
  ((select id from public.recipes where slug = 'no-knead-country-loaf'), 6, 'Cool on a rack for at least 1 hour before slicing.');
insert into public.recipe_tips (recipe_id, position, tip) values
  ((select id from public.recipes where slug = 'no-knead-country-loaf'), 1, 'The loaf is done when it sounds hollow when tapped underneath.');
insert into public.recipe_substitutions (recipe_id, position, ingredient, substitute) values
  ((select id from public.recipes where slug = 'no-knead-country-loaf'), 1, 'strong bread flour', 'Swap up to 150 g for whole wheat or rye flour, adding 20 ml extra water');
