insert into public.recipe_steps (recipe_id, step_number, instruction) values
  ((select id from public.recipes where slug = 'beef-bibimbap'), 1, 'Cook the rice according to the packet and keep warm.'),
  ((select id from public.recipes where slug = 'beef-bibimbap'), 2, 'Mix the beef with 2 tbsp soy sauce, the sugar, half the garlic and 1 tsp sesame oil. Stir-fry in a hot pan until browned, then set aside.'),
  ((select id from public.recipes where slug = 'beef-bibimbap'), 3, 'Blanch the spinach and bean sprouts separately for 1 minute each. Squeeze dry and season each with a little sesame oil, soy sauce and garlic.'),
  ((select id from public.recipes where slug = 'beef-bibimbap'), 4, 'Stir-fry the carrot, zucchini and mushrooms separately in a little vegetable oil for 1–2 minutes each, seasoning lightly.'),
  ((select id from public.recipes where slug = 'beef-bibimbap'), 5, 'Fry the eggs sunny-side up. Mix the gochujang with 1 tbsp sesame oil and 1 tbsp water.'),
  ((select id from public.recipes where slug = 'beef-bibimbap'), 6, 'Divide the rice between bowls, arrange the vegetables and beef in sections, top with an egg and sesame seeds, and serve with the sauce.');
insert into public.recipe_tips (recipe_id, position, tip) values
  ((select id from public.recipes where slug = 'beef-bibimbap'), 1, 'Mix everything together vigorously at the table. That''s the point of bibimbap.');
