insert into public.recipe_ingredients (recipe_id, ingredient_id, position, quantity, unit, note, is_optional) values
  ((select id from public.recipes where slug = 'spinach-ricotta-ravioli'), 'flour', 1, 300, 'g', 'or Italian ''00'' flour', false),
  ((select id from public.recipes where slug = 'spinach-ricotta-ravioli'), 'eggs', 2, 3, null, null, false),
