  ((select id from public.recipes where slug = 'spinach-ricotta-ravioli'), 'parmesan', 5, 60, 'g', 'finely grated, plus extra to serve', false),
  ((select id from public.recipes where slug = 'spinach-ricotta-ravioli'), 'lemon', 6, 1, null, 'zested', false),
  ((select id from public.recipes where slug = 'spinach-ricotta-ravioli'), 'nutmeg', 7, 1, 'pinch', null, false),
