insert into public.recipe_steps (recipe_id, step_number, instruction) values
  ((select id from public.recipes where slug = 'spinach-ricotta-ravioli'), 1, 'Tip the flour onto a clean surface, make a well and crack in the eggs. Mix with a fork, then knead for 8–10 minutes until smooth. Wrap and rest for 30 minutes.'),
  ((select id from public.recipes where slug = 'spinach-ricotta-ravioli'), 2, 'Wilt the spinach in a dry pan, cool, then squeeze out as much water as possible and chop finely. Mix with the ricotta, parmesan, lemon zest, nutmeg, salt and pepper.'),
  ((select id from public.recipes where slug = 'spinach-ricotta-ravioli'), 3, 'Roll the pasta into thin sheets with a pasta machine or rolling pin, until you can just see your hand through it.'),
  ((select id from public.recipes where slug = 'spinach-ricotta-ravioli'), 4, 'Place teaspoons of filling 4 cm apart along one sheet. Brush around them with water, lay a second sheet over the top and press out the air. Cut into squares.'),
  ((select id from public.recipes where slug = 'spinach-ricotta-ravioli'), 5, 'Cook the ravioli in a large pan of well-salted boiling water for 3–4 minutes, until they float and the pasta is tender.'),
  ((select id from public.recipes where slug = 'spinach-ricotta-ravioli'), 6, 'Meanwhile, melt the butter with the sage until nutty and the leaves crisp. Toss the drained ravioli in the butter and serve with extra parmesan.');
insert into public.recipe_tips (recipe_id, position, tip) values
  ((select id from public.recipes where slug = 'spinach-ricotta-ravioli'), 1, 'Press out every air pocket when sealing, or the ravioli may burst while cooking.');
insert into public.recipe_substitutions (recipe_id, position, ingredient, substitute) values
  ((select id from public.recipes where slug = 'spinach-ricotta-ravioli'), 1, 'spinach', 'Wild garlic, chard or roasted butternut squash');
